func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/info", wrapper.GetSystemInfo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/settings", wrapper.GetSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/settings", wrapper.UpdateSettings)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/settings/notifications/test", wrapper.TestNotification)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/session", wrapper.GetSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/password", wrapper.ChangePassword)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/mfa/totp", wrapper.VerifyTotp)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/mfa/webauthn/begin", wrapper.BeginWebauthnLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/mfa/webauthn/finish", wrapper.FinishWebauthnLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/totp/enroll", wrapper.BeginTotpEnrollment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/totp/confirm", wrapper.ConfirmTotpEnrollment)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/auth/totp", wrapper.DisableTotp)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/webauthn/register/begin", wrapper.BeginWebauthnRegistration)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/webauthn/register/finish", wrapper.FinishWebauthnRegistration)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/webauthn/credentials", wrapper.ListWebauthnCredentials)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/auth/webauthn/credentials/{credentialId}", wrapper.DeleteWebauthnCredential)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users", wrapper.CreateUser)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/users/{userId}", wrapper.DeleteUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{userId}", wrapper.GetUser)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/users/{userId}", wrapper.UpdateUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users/{userId}/reset-password", wrapper.ResetUserPassword)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users/{userId}/reset-mfa", wrapper.ResetUserMfa)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{userId}/role-bindings", wrapper.GetUserRoleBindings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/users/{userId}/role-bindings", wrapper.SetUserRoleBindings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/roles", wrapper.ListRoles)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/host-groups", wrapper.ListHostGroups)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/host-groups", wrapper.CreateHostGroup)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/host-groups/{groupId}", wrapper.DeleteHostGroup)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/host-groups/{groupId}", wrapper.UpdateHostGroup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts", wrapper.ListHosts)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/hosts/{hostId}", wrapper.DecommissionHost)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}", wrapper.GetHost)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/hosts/{hostId}", wrapper.UpdateHost)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/inventory", wrapper.GetHostInventory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/packages", wrapper.ListHostPackages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/updates", wrapper.GetHostUpdates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/processes", wrapper.GetHostProcesses)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/checks", wrapper.GetHostChecks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/metrics/{panel}", wrapper.GetHostMetrics)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/hosts/{hostId}/shell", wrapper.CreateShellSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{hostId}/shell/{sessionId}", wrapper.ConnectShell)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/shell-sessions", wrapper.ListShellSessions)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/shell-sessions/{sessionId}", wrapper.TerminateShellSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/shell-sessions/{sessionId}/recording", wrapper.GetShellRecording)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/enrollment-tokens", wrapper.ListEnrollmentTokens)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/enrollment-tokens", wrapper.CreateEnrollmentToken)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/enrollment-tokens/{tokenId}", wrapper.RevokeEnrollmentToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs", wrapper.ListJobs)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/jobs", wrapper.CreateJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs/{jobId}", wrapper.GetJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs/{jobId}/targets", wrapper.ListJobTargets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs/{jobId}/targets/{hostId}/output", wrapper.GetJobOutput)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/jobs/{jobId}/cancel", wrapper.CancelJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/updates", wrapper.ListFleetUpdates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/audit", wrapper.ListAudit)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/audit/verify", wrapper.VerifyAudit)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/alerts", wrapper.ListAlerts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/alertmanager/webhook", wrapper.AlertmanagerWebhook)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/security/summary", wrapper.GetSecuritySummary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/events", wrapper.ConnectEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dashboard", wrapper.GetDashboard)

	return m
}

